277	    /**
278	     * Save an owner, enforcing the create-time business rules.
279	     *
280	     * <p>Duplicate rejection on create is expressed solely through the single {@code identityKey} (the
281	     * SHA-256 hex over the normalized telephone, lower-cased email and last-name Soundex, see
282	     * {@link Owner#identityKey(String, String, String)}): {@link #assertIdentityIsUnique(Owner)}
283	     * rejects an owner whose whole identity key already belongs to another owner. Because the
284	     * telephone is part of the key, two members of the same household (same last name and postcode)
285	     * with different telephones have different identity keys and are both allowed; the former separate
286	     * household-duplicate 409 no longer applies. Such an undeclared household member is created but
287	     * flagged as a possible (suspected) duplicate when its last-name Soundex and postcode match an
288	     * existing owner (see {@link #assignPossibleDuplicate(Owner, boolean)}), whereas a declared
289	     * household member ({@code sharesHousehold} set) is left unflagged; {@code sharesHousehold} now
290	     * governs only that flagging. This keeps the sole {@code POST /api/owners} duplicate rule in one
291	     * place and lets household members coexist, which the household membership-level ceiling (see
292	     * {@link #computeMembershipLevel(Owner)}) relies on to compare a new owner against the existing
293	     * members.
294	     */
295	    @Override
296	    @Transactional
297	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
298	        boolean isCreate = owner.isNew();
299	        assertEmailDomainAllowed(owner);
300	        assertIdentityIsUnique(owner);
301	        if (owner.isNew()) {
302	            assertCityHasCapacity(owner);
303	        }
304	        if (owner.getRegistrationDate() == null) {
305	            owner.setRegistrationDate(LocalDate.now());
306	        }
307	        assertRegistrationDateNotInFuture(owner);
308	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
309	        if (owner.isNew()) {
310	            assertDailyRegistrationLimit(owner);
311	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
312	        }
313	        if (owner.isNew() && owner.getCustomerCode() == null) {
314	            owner.setCustomerCode(generateCustomerCode(owner));
315	        }
316	        if (owner.isNew() && owner.getNamesakeCount() == null) {
317	            owner.setNamesakeCount(countNamesakes(owner));
318	        }
319	        if (owner.isNew() && owner.getHouseholdCount() == null) {
320	            owner.setHouseholdCount(countHouseholdMembers(owner));
321	        }
322	        if (owner.isNew() && owner.getMembershipLevel() == null) {
323	            owner.setMembershipLevel(computeMembershipLevel(owner));
324	        }
325	        if (owner.isNew()) {
326	            assignPossibleDuplicate(owner, sharesHousehold);
327	        }
328	        ownerRepository.save(owner);
329	        if (isCreate) {
330	            String membershipNumber = Owner.membershipNumber(owner.getCustomerCode(),
331	                owner.getRegistrationDate());
332	            int membershipLevel = owner.effectiveMembershipLevel();
333	            AUDIT.info("owner created id={} customerCode={} registrationDate={} "
334	                    + "membershipLevel={} membershipNumber={}",
335	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
336	                membershipLevel, membershipNumber);
337	        }
338	    }
339	
340	    /**
341	     * Count the existing owners that, at the moment this owner is created, share its first name
342	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
343	     * it never counts itself. This value is deterministic given the current data, so it is computed
344	     * once at creation time and stored.
345	     */
346	    private Integer countNamesakes(Owner owner) {
347	        String firstName = owner.getFirstName();
348	        String lastName = owner.getLastName();
349	        if (firstName == null || lastName == null) {
350	            return 0;
351	        }
352	        return (int) ownerRepository.findAll().stream()
353	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
354	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
355	                && lastName.equalsIgnoreCase(existing.getLastName()))
356	            .count();
357	    }
358	
359	    /**
360	     * Count the members of this owner's household at the moment it is created, i.e. the number of
361	     * owners sharing its household id (same last name and postcode, see
362	     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
363	     * household id (missing last name or postcode) is counted as a single-member household. The value
364	     * is deterministic given the current data, so it is computed once at creation time and stored.
365	     */
366	    private Integer countHouseholdMembers(Owner owner) {
367	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
368	        if (householdId == null) {
369	            return 1;
370	        }
371	        long others = ownerRepository.findAll().stream()
372	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
373	            .filter(existing -> householdId.equals(
374	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
375	            .count();
376	        return (int) others + 1;
377	    }
378	
379	    /**
380	     * Compute a newly created owner's {@code membershipLevel} after applying the household level
381	     * ceiling, the value stored on the owner so every later read returns the capped level. The
382	     * owner's own uncapped level is first derived from its membership points (see
383	     * {@link Owner#membershipLevel(int)} and
384	     * {@link Owner#membershipPoints(Integer, String, Integer, java.time.LocalDate)}). The ceiling is
385	     * then one above the current maximum {@code membershipLevel} among the owner's existing household
386	     * members&mdash;other owners sharing its household id (same last name and postcode, see
387	     * {@link Owner#householdId(String, String)}), excluding soft-deleted owners and the owner itself.
388	     * Each level (the owner's own uncapped level and each member's) is read through
389	     * {@link Owner#effectiveMembershipLevel()}, the single resolver shared with the read-side mapping.
390	     * The returned level is the smaller of the uncapped level and that ceiling. When the owner has no
391	     * derivable household id or no existing household member, no ceiling applies and the uncapped
392	     * level is returned.
393	     */
394	    private Integer computeMembershipLevel(Owner owner) {
395	        int uncapped = owner.effectiveMembershipLevel();
396	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
397	        if (householdId == null) {
398	            return uncapped;
399	        }
400	        Integer maxHouseholdLevel = ownerRepository.findAll().stream()
401	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
402	            .filter(existing -> !existing.isDeleted())
403	            .filter(existing -> householdId.equals(
404	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
405	            .map(Owner::effectiveMembershipLevel)
406	            .max(Integer::compareTo)
407	            .orElse(null);
408	        if (maxHouseholdLevel == null) {
409	            return uncapped;
410	        }
411	        return Math.min(uncapped, maxHouseholdLevel + 1);
412	    }
413	
414	    /**
415	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
416	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
417	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
418	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
419	     * base value is deterministic in those fields and carries no sequence number (see
420	     * {@link Owner#customerCode(String, String, String)}).
421	     *
422	     * <p>When that computed code collides with an existing owner's {@code customerCode}, this appends
423	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g. a second owner
424	     * computing {@code 'NSW-1A2B3C4D'} is stored as {@code 'NSW-1A2B3C4D-2'}), so distinct owners always
425	     * receive distinct customer codes. A {@code null} computed code (missing telephone or last name) is
426	     * returned unchanged.
427	     */
428	    private String generateCustomerCode(Owner owner) {
429	        String base = Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
430	        if (base == null) {
431	            return null;
432	        }
433	        Set<String> existing = ownerRepository.findAll().stream()
434	            .filter(other -> !Objects.equals(other.getId(), owner.getId()))
435	            .map(Owner::getCustomerCode)
436	            .filter(Objects::nonNull)
437	            .collect(Collectors.toSet());
438	        if (!existing.contains(base)) {
439	            return base;
440	        }
441	        int n = 2;
442	        while (existing.contains(base + "-" + n)) {
443	            n++;
444	        }
445	        return base + "-" + n;
446	    }
447	
448	    /**
449	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
450	     * duplicate (an owner sharing this owner's whole {@code identityKey}) has already been rejected by
451	     * {@link #assertIdentityIsUnique(Owner)} before this runs. This detects the weaker overlap: an
452	     * existing owner whose identity key <em>differs</em> but whose last-name Soundex (see
453	     * {@link Owner#soundex(String)}) and postcode both match this owner. When such an owner exists,
454	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the matching
455	     * owner's id (the lowest id when several match); otherwise {@code possibleDuplicate} is set
456	     * {@code false} and {@code possibleDuplicateOf} left unset. In particular, two owners with the same
457	     * last name and postcode but different telephones are no longer a hard duplicate and surface here
458	     * as a soft match.
459	     *
460	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
461	     * deliberately joins an existing household, so it is left unflagged.
462	     */
463	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
464	        if (sharesHousehold) {
465	            owner.setPossibleDuplicate(false);
466	            owner.setPossibleDuplicateOf(null);
467	            return;
468	        }
469	        String identityKey = Owner.identityKey(
470	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
471	        String soundex = Owner.soundex(owner.getLastName());
472	        String postcode = owner.getPostcode();
473	        Integer match = null;
474	        if (soundex != null && !soundex.isEmpty() && postcode != null) {
475	            match = ownerRepository.findAll().stream()
476	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
477	                .filter(existing -> !existing.isDeleted())
478	                .filter(existing -> !identityKey.equals(Owner.identityKey(
479	                    existing.getTelephone(), existing.getEmail(), existing.getLastName())))
480	                .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName())))
481	                .filter(existing -> postcode.equals(existing.getPostcode()))
482	                .map(Owner::getId)
483	                .filter(Objects::nonNull)
484	                .min(Integer::compareTo)
485	                .orElse(null);
486	        }
487	        owner.setPossibleDuplicate(match != null);
488	        owner.setPossibleDuplicateOf(match);
489	    }
490	
491	    /**
492	     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
493	     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
494	     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
495	     * constraint.
496	     */
497	    private void assertEmailDomainAllowed(Owner owner) {
498	        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
499	            throw new DisposableEmailDomainException(owner.getEmail());
500	        }
501	    }
502	
503	    /**
504	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
505	     * {@link DuplicateIdentityException} if one does. Duplicate detection is now the single
506	     * {@code identityKey}: the SHA-256 hex over the normalized telephone, lower-cased email and the
507	     * Soundex of the last name (see {@link Owner#identityKey(String, String, String)}). Two owners
508	     * are a hard duplicate exactly when their whole identity keys are equal.
509	     *
510	     * <p>Because the telephone is part of the key, two members of the same household (same last name
511	     * and postcode) with different telephones have different identity keys and are both allowed —
512	     * they surface instead as a soft match (see {@link #assignPossibleDuplicate(Owner, boolean)}).
513	     * The email-domain blocklist is applied first (see {@link #assertEmailDomainAllowed(Owner)}), and
514	     * soft-deleted owners are ignored. The owner being saved is excluded by id so updating an owner in
515	     * place never conflicts with itself.
516	     */
517	    private void assertIdentityIsUnique(Owner owner) {
518	        String identityKey = Owner.identityKey(
519	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
520	        boolean duplicate = ownerRepository.findAll().stream()
521	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
522	            .filter(existing -> !existing.isDeleted())
523	            .map(existing -> Owner.identityKey(
524	                existing.getTelephone(), existing.getEmail(), existing.getLastName()))
525	            .anyMatch(identityKey::equals);
526	        if (duplicate) {
527	            throw new DuplicateIdentityException(identityKey);
528	        }
529	    }
530	
531	    /**
532	     * Enforce that the owner's city has not yet reached its capacity, throwing
533	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
534	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
535	     */
536	    private void assertCityHasCapacity(Owner owner) {
537	        String city = owner.getCity();
538	        if (city == null) {
539	            return;
540	        }
541	        long count = ownerRepository.findAll().stream()
542	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
543	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
544	            .count();
545	        if (count >= MAX_OWNERS_PER_CITY) {
546	            throw new CityAtCapacityException(city);
547	        }
548	    }
549	
550	    /**
551	     * Enforce that the owner's registration date is not later than the current server date, throwing
552	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
553	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
554	     * harmless no-op for that case.
555	     */
556	    private void assertRegistrationDateNotInFuture(Owner owner) {
557	        LocalDate registrationDate = owner.getRegistrationDate();
558	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
559	            throw new FutureRegistrationDateException(registrationDate);
560	        }
561	    }
562	
563	    /**
564	     * Roll a registration date forward to the next business day. A date that falls on a Saturday,
565	     * Sunday or a listed public holiday is advanced to the following non-holiday weekday; a plain
566	     * weekday is returned unchanged. This is applied to the effective registration date (whether
567	     * supplied in the request or defaulted to the server date) so that every value derived from
568	     * it&mdash;such as the membership number's year segment and the daily create-limit
569	     * counting&mdash;uses the adjusted business day.
570	     */
571	    private static LocalDate rollToBusinessDay(LocalDate date) {
572	        if (date == null) {
573	            return null;
574	        }
575	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
576	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
577	                || PUBLIC_HOLIDAYS.contains(date)) {
578	            date = date.plusDays(1);
579	        }
580	        return date;
581	    }
582	
583	    /**
584	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
585	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
586	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
587	     * is excluded by id.
588	     */
589	    private void assertDailyRegistrationLimit(Owner owner) {
590	        LocalDate registrationDate = owner.getRegistrationDate();
591	        if (registrationDate == null) {
592	            return;
593	        }
594	        long count = ownerRepository.findAll().stream()
595	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
596	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
597	            .count();
598	        if (count >= MAX_OWNERS_PER_DAY) {
599	            throw new DailyRegistrationLimitException(registrationDate);
600	        }
601	    }
602	
603	    /**
604	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
605	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
606	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
607	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
608	     * stored on the owner.
609	     */
610	    private boolean computeBulkSignupWarning(Owner owner) {
611	        LocalDate registrationDate = owner.getRegistrationDate();
612	        if (registrationDate == null) {
613	            return false;
614	        }
615	        long count = ownerRepository.findAll().stream()
616	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
617	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
618	            .count();
619	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
620	    }
621	
622	    @Override
623	    @Transactional(readOnly = true)
624	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
625	        return ownerRepository.findByLastName(lastName);
626	    }
627	
628	    @Override
629	    @Transactional(readOnly = true)
630	    public Collection<Visit> findVisitsByPetId(int petId) {
631	        return visitRepository.findByPetId(petId);
632	    }
633	
634	    @Override
635	    @Transactional(readOnly = true)
636	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
637	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
638	    }
639	
640	    private <T> T findEntityById(Supplier<T> supplier) {
641	        try {
642	            return supplier.get();
643	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
644	            // Just ignore not found exceptions for Jdbc/Jpa realization
645	            return null;
646	        }
647	    }
648	
649	}
